// ADD FULL ADVERT – keeps the Job Tracker row and adds the full Reed advert text
return $input.all().map((item, i) => {
  const row = $("Max 3 Per Run").itemMatching(i).json;
  return { json: { ...row, jobDescription: item.json.error ? "" : (item.json.jobDescription || "") } };
});

// FORMAT INTERVIEW PREP
// Turns the AI's answer into readable text and checks every CV quote really
// appears in the CV (quotes that don't are marked "check this"), and flags any number
// in an answer outline that does not appear in the CV (a sign of an invented detail).
const norm = (s) => String(s || "").toLowerCase().replace(/[^a-z0-9+#%.]+/g, " ").trim();
return $input.all().map((item, i) => {
  const job = $("Build Prep Requests").itemMatching(i).json;
  const cv = norm(job.cv_text);
  let p;
  try { p = JSON.parse(item.json.choices[0].message.content); }
  catch (e) { return { json: { id: job.row_id, ok: false, error: String(item.json.error?.message || e.message).slice(0, 200) } }; }
  const cvRaw = String(job.cv_text);
  const unq = (s) => String(s || "").trim().replace(/^["'“”]+|["'“”]+$/g, "");
  let checked = 0, unverified = 0, invented = 0;
  const qs = (p.likely_questions || []).map((q, n) => {
    let ev = "";
    const quote = unq(q.cv_evidence);
    const nums = (String(q.answer_outline).match(/\d+(?:[.,]\d+)?%?/g) || []).filter((x) => !cvRaw.includes(x));
    const numWarn = nums.length ? "   ⚠️ Check: " + nums.join(", ") + " is not in your CV – remove it unless it is true" : "";
    if (nums.length) invented++;
    if (quote) {
      checked++;
      if (cv.includes(norm(quote))) ev = "   From your CV: \"" + quote + "\"";
      else { unverified++; ev = "   ⚠️ Check this: the AI's CV quote was not found in your CV"; }
    }
    return [(n + 1) + ". " + q.question, "   Why they ask: " + q.why_they_ask, "   How to answer: " + q.answer_outline, ev, numWarn].filter(Boolean).join("\n");
  });
  const list = (arr) => (arr || []).map((x) => "- " + x).join("\n");
  const text = [
    "INTERVIEW PREP – " + job.title + " at " + job.company,
    "",
    "YOUR ONE-MINUTE PITCH",
    p.one_minute_pitch,
    "",
    "LIKELY QUESTIONS",
    qs.join("\n\n"),
    "",
    "TOPICS TO REVISE",
    list(p.topics_to_revise),
    "",
    "QUESTIONS TO ASK THEM",
    list(p.questions_to_ask_them),
    "",
    "RESEARCH BEFORE THE INTERVIEW",
    list(p.research_checklist),
    "",
    "Quality check: " + (checked - unverified) + " of " + checked + " CV quotes verified; " + invented + " answer(s) contain numbers not in your CV.",
    "These are suggestions written by AI. Replace anything that is not true for you, and fill every [add your own example]."
  ].join("\n");
  return { json: { id: job.row_id, ok: true, interview_prep: text } };
});
